mapper.select:
SELECT EXISTS(
  SELECT 1 FROM audit_archive_member m JOIN platform_audit p ON p.audit_attempt_id=m.attempt_id
  JOIN platform_command c ON c.tenant_id=p.tenant_id AND c.actor_id=p.actor_id
    AND c.operation=p.operation AND c.command_key=p.command_key
  WHERE m.batch_id=#{id}
)

mapper.insert:
INSERT INTO audit_archive_effect_locator(effect_id,batch_id,attempt_id,action_code)
SELECT p.id,m.batch_id,m.attempt_id,p.audit_action_code
FROM audit_archive_member m JOIN platform_audit p ON p.audit_attempt_id=m.attempt_id WHERE m.batch_id=#{id}
